import { readFileSync, writeFileSync } from 'fs';
import path from 'path';
import crypto from 'crypto';
import { spawnSync } from 'child_process';
import { fileURLToPath } from 'url';
import { snapshot, captureResult } from '../check.mjs';

const trialDir = path.dirname(fileURLToPath(import.meta.url));
const target = 'CHECKOUT_ROOT';
const processId = 'i542_migrate_spec_id_refs';
const artifactId = 'spec_id_refs';
const newId = 'SPEC_single_producer_constraint';
const heading = '### 15.1 単一生成元制約';
const refRe = /§15\.1(?![0-9.])/g;
const token = `[[${newId}]]`;
const checks = [];
const asserts = [];
