const canon = (v) => JSON.stringify(v, (k, x) => (x && typeof x === 'object' && !Array.isArray(x) ? Object.fromEntries(Object.keys(x).sort().map((y) => [y, x[y]])) : x));
const readyIds = (x) => (Array.isArray(x) ? x : x.ready).map((r) => (typeof r === 'string' ? r : r.id));
const saveChecks = () => writeFileSync(path.join(trialDir, 'checks.json'), JSON.stringify({ checks, assertions: asserts }, null, 2) + '\n');

function assert(name, ok) {
  asserts.push({ name, ok: Boolean(ok) });
  if (!ok) throw new Error(`assertion failed: ${name}`);
}

function run(cmd, args) {
  const r = spawnSync(cmd === 'node' ? process.execPath : cmd, args, { cwd: target, encoding: 'utf8' });
  checks.push({ command: [cmd, ...args], status: r.status, stdout: r.stdout, stderr: r.stderr });
  return r;
}

function main() {
  const preSnapshot = JSON.parse(readFileSync(path.join(trialDir, 'snapshot.json'), 'utf8'));
