  const live = run('node', ['packages/cli/dist/cli.js', 'status', 'ready', '.pfdsl/roadmap.pfdsl', '--json']);
  assert('live ready exits 0', live.status === 0);
  const liveReady = JSON.parse(live.stdout);
  assert('ready ok on both sets', liveReady.ok === true && frozenReady.ok !== false);
  assert('process in both ready sets', readyIds(frozenReady).includes(processId) && readyIds(liveReady).includes(processId));
  assert('captureResult versions match frozen', Object.keys(preSnapshot.versions).length === 3 && canon(captureResult(preSnapshot, target).versions) === canon(preSnapshot.versions));
  const absent = run('node', ['scripts/get-spec-id.mjs', newId]);
  assert('new ID absent', absent.status === 1 && /not defined|undefined|未定義/i.test(absent.stdout + absent.stderr));
