  const changedPaths = keys.filter((k) => canon(preSnapshot.manifest[k]) !== canon(post.manifest[k])).sort();
  assert('changed paths are the two targets', canon(changedPaths) === canon(['.pfdsl/roadmap.pfdsl', 'docs/spec/spec.md']));
  const evidence = {
    schemaVersion: 0,
    runId: crypto.randomUUID(),
    processId,
    workItemIds: ['542'],
    versions: preSnapshot.versions,
    resultVersions: post.versions,
    changedPaths,
