  writeFileSync(path.join(trialDir, 'result.json'), out.stdout);
  const result = JSON.parse(out.stdout || 'null');
  assert('checker exits 0 with PASS', out.status === 0 && result !== null && result.status === 'PASS');
  console.log(`PASS ${processId} run=${evidence.runId} changed=${changedPaths.join(',')} ${artifactId}=wip`);
}

try {
  main();
} catch (e) {
  console.error(e.message);
  process.exitCode = 1;
} finally {
  saveChecks();
}
